def transform(grid):
    h, w = len(grid), len(grid[0])

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1

    background = max(counts, key=counts.get)
    line_color = max((v for v in counts if v != background),
                     key=lambda v: counts[v])

    rows = [r for r in range(h)
            if sum(grid[r][c] != background for c in range(w)) / w > 0.55]
    cols = [c for c in range(w)
            if sum(grid[r][c] != background for r in range(h)) / h > 0.55]

    def special(r, c):
        return grid[r][c] not in (background, line_color)

    active_rows = [i for i, r in enumerate(rows)
                   if any(special(r, c) for c in cols)]
    active_cols = [i for i, c in enumerate(cols)
                   if any(special(r, c) for r in rows)]

    if active_rows:
        rows = rows[active_rows[0]:active_rows[-1] + 1]
    if active_cols:
        cols = cols[active_cols[0]:active_cols[-1] + 1]

    out = []
    for i in range(len(rows) - 1):
        line = []
        for j in range(len(cols) - 1):
            a = grid[rows[i]][cols[j]]
            b = grid[rows[i]][cols[j + 1]]
            c = grid[rows[i + 1]][cols[j]]
            d = grid[rows[i + 1]][cols[j + 1]]
            if a == b == c == d and a not in (background, line_color):
                line.append(a)
            else:
                line.append(background)
        out.append(line)
    return out
